const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countOfType = (items: Item[], type: string): number =>
  items.filter((item) => item.type === type).length;

/**
 * Only knows about a policy that is exactly one block of runes. The general
 * rule — count blocks per component type, charge the remainder per item — is
 * not yet driven out by a test, so this stays deliberately narrow.
 */
const formsASingleBlock = (items: Item[]): boolean =>
  countOfType(items, "rune") === BLOCK_SIZE;

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const policyBasePremium = (items: Item[]): number =>
  formsASingleBlock(items) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(items);
